function replicaNotice(name: string): string {
    for (const [re, brand] of REPLICA_BRANDS) {
        if (re.test(name)) return `Replica product, not an original ${brand} product.`;
    }
    return 'Replica product, not an original brand product.';
}

const p = (id: number, name: string, category: Product['category'], price: string, dateLabel: string,
    details: string[], imgs: [number, number, number, number, number][], channel: 'bi' | 'wm', gender?: 'L' | 'M' | 'U',
    authenticity?: string, authShort?: string): Product => ({
    id, name, category, gender, price, dateLabel, details, authShort,
    authenticity: authenticity ? replicaNotice(name) : undefined,
    source: channel,
    photos: imgs.map(([s, x, y, w, h], i) => ({ s, x, y, w, h, alt: `${name}, photo ${i + 1}` })),
});

const q = (id: number, name: string, price: string, dateLabel: string, details: string[], imgs: [string, number, number][], gender: 'L' | 'M' | 'U', authenticity: string): Product => ({
    id, name, category: 'Sunglass', gender, price, dateLabel, details, authenticity, source: '',
    photos: imgs.map(([src, w, h], i) => ({ s: -1, x: 0, y: 0, w, h, src, alt: `${name}, photo ${i + 1}` })),
});

